type ScopeFilter =
  | { type: "all";         fields?: string[] }                                          // no row restriction
  | { type: "none";        fields?: never }                                             // no access
  | { type: "self";        id: string;                            fields?: string[] }   // single row by id
  | { type: "notSelf";     id: string;                            fields?: string[] }   // exclude single row
  | { type: "children";    parentId: string;                      fields?: string[] }   // rows by parent
  | { type: "notChildren"; parentId: string;                      fields?: string[] }   // exclude by parent
  | { type: "meta";        field: string; values: string[];
                           negate?: boolean;                      fields?: string[] }   // app-owned metadata JSON path
  | { type: "field";       entity: string; field: string;
                           value: string | string[];
                           negate?: boolean;                      fields?: string[] }   // generic field match
  | { type: "composite";   filters: ScopeFilter[];
                           logic: "and" | "or";                   fields?: string[] }   // combine filters (logic required)
  | { type: "traversal";
      hops: Array<{ fromEntity: string; fkField: string; toEntity: string }>;
      finalCondition: ScopeFilter;
                                                                  fields?: string[] }; // FK chain + condition on last entity

interface ScopeFilterBuilder {
  compile(entity: string, filter: ScopeFilter): ResolvedScope;
  buildWhere(entity: string, filter: ScopeFilter): SQL | undefined;
  buildSelect(entity: string, filter: ScopeFilter): Record<string, unknown>;
}

function buildWhere(filter: ScopeFilter): SQL {
  switch (filter.type) {
    case "all":         return sql`TRUE`;
    case "none":        return sql`FALSE`;
    case "self":        return eq(table.id, filter.id);
    // … handle every variant
    default:            return assertNever(filter);   // compile-time error if any variant is missed
  }
}

